for (let i = 5; i > 0; i--) {
  const circle = penpot.createEllipse();
  const size = i * 40;
  circle.resize(size, size);
  circle.x = center.x - (size / 2);
  circle.y = center.y - (size / 2);
  circle.fills = [{fillColor: colors[i - 1]}];
}

