const config = {width: 80,height: 30,radius: 5,rectColor: '#FF6B6B',text: 'PROMO',fontSize: 14,fontWeight: '700',textColor: '#FFFFFF',x: 200,y: 200};
const badgeRect = penpot.createRectangle();
badgeRect.resize(config.width, config.height);
badgeRect.borderRadius = config.radius;
badgeRect.fills = [{ fillColor: config.rectColor }];
const badgeText = penpot.createText(config.text);
badgeText.fontSize = config.fontSize;
badgeText.fontWeight = config.fontWeight;
badgeText.fills = [{ fillColor: config.textColor }];
await badgeText.loadFont();
const group = penpot.group([badgeRect, badgeText]);
group.name = 'Marketing Badge';
group.x = config.x;
group.y = config.y;
badgeText.x = (config.width - badgeText.width) / 2;
badgeText.y = (config.height - badgeText.height) / 2;

